const email = $json.work_email || '';
const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const freeDomains = ['gmail.com','yahoo.com','hotmail.com','outlook.com','aol.com','icloud.com'];
const domain = email.split('@')[1] || '';
const validSyntax = emailRe.test(email);
const isFreeDomain = freeDomains.includes(domain);

return [{
  json: {
    ...$json,
    email_valid: validSyntax,
    free_email_domain: isFreeDomain,
    flag_for_review: isFreeDomain
  }
}];

const input = $('CODE - Validate Email/Domain').first().json;
// Some frontend selects post snake_case codes (e.g. business_type = 'real_estate_brokerage')
// while other fields post the literal Section 5 label text (e.g. response_time = '<1 hour').
// Stripping underscores (never hyphens - '16-50' and '5-15 min' rely on the hyphen) makes
// matching resilient to either convention without needing a second lookup table.
const n = (v) => String(v ?? '').trim().toLowerCase().replace(/_/g, ' ');
const pick = (map, value, fallback = 0) => map[n(value)] ?? fallback;

// Load Config tab (Key/Value rows) so thresholds are never hard-coded in more than one node.
const configRows = $('GS - Read Config').all();
const config = {};
for (const row of configRows) {
  const key = row.json.Key ?? row.json.key;
  const value = row.json.Value ?? row.json.value;
  if (key) config[key] = value;
}

// Map keys below are normalized (trim+lowercase) versions of the EXACT option labels
// from the Assessment Form Specification (spec section 5), not the illustrative
// wording used in the section 7.5 example code, which does not match the real
// form options and would silently zero out almost every category.
const system = {
  centralization: pick({yes:15, partially:8, no:0, 'not sure':3}, input.all_leads_centralized),
  storage: pick({crm:15, 'property software':13, sheets:7, email:3, 'different systems':0, 'not sure':2}, input.lead_storage),
  response: pick({immediate:15, '5-15 min':13, '<1 hour':9, 'same day':5, '>1 day':0, 'depends on staff':3}, input.response_time),
  assignment: pick({automatic:15, 'manager manually':8, 'agents select':5, 'email/group':3, 'no formal process':0}, input.assignment_method),
  followup: pick({'fully automated':15, 'crm reminders':11, 'personal calendars':7, sheets:4, memory:1, 'no consistent process':0}, input.followup_method),
  missedCall: pick({'auto sms':10, 'task created':8, 'crm log':6, 'manual check':3, 'no process':0, 'not sure':1}, input.missed_call_process),
  visibility: pick({'live dashboard':15, partial:10, 'manual reports':5, no:0, 'not sure':2}, input.management_visibility)
};

const sources = Array.isArray(input.lead_sources)
  ? input.lead_sources
  : String(input.lead_sources ?? '').split(',').map(s => s.trim()).filter(Boolean);
const sourceCount = sources.length;

const qualification = {
  team: pick({'just me':2, '2-5':8, '6-15':14, '16-50':18, '50+':20}, input.team_size),
  volume: pick({'<10':2, '10-30':8, '31-75':15, '76-200':21, '200+':25, 'not sure':5}, input.monthly_leads),
  sources: sourceCount >= 4 ? 15 : sourceCount === 3 ? 11 : sourceCount === 2 ? 7 : sourceCount === 1 ? 3 : 0,
  timeline: pick({immediately:20, '30 days':17, '90 days':12, 'later this year':6, researching:2}, input.improvement_timeline),
  review: pick({yes:10, maybe:5, no:0}, input.personal_review_requested),
  fit: pick({'property management':10, 'real estate brokerage':10, 'mortgage brokerage':10, 'real estate investment':10, 'real estate marketing agency':8, other:3}, input.business_type)
};

const systemHealthScore = Object.values(system).reduce((a,b) => a+b, 0);
const qualificationScore = Object.values(qualification).reduce((a,b) => a+b, 0);

const aGradeMin = Number(config.A_GRADE_MIN) || 70;
const bGradeMin = Number(config.B_GRADE_MIN) || 45;
const grade = qualificationScore >= aGradeMin ? 'A' : qualificationScore >= bGradeMin ? 'B' : 'C';

const categoryLabels = {
  centralization: 'Lead centralization', storage: 'Lead storage', response: 'Response speed',
  assignment: 'Lead assignment', followup: 'Follow-up', missedCall: 'Missed calls', visibility: 'Management visibility'
};

const weakest = Object.entries(system)
  .sort((a,b) => a[1]-b[1])
  .slice(0,3)
  .map(([key,score]) => ({ category: categoryLabels[key], score }));

// Spec 7.4 has a 4th row ('very low qualification' -> educational nurture, no custom
// proposal yet) that is functionally the same population as a C-grade lead (spec 7.3:
// automated educational result and light nurture only, no custom Loom/proposal), so it
// is keyed off bGradeMin here rather than inventing a second undefined threshold.
const recommendedOffer = qualificationScore >= 75 && systemHealthScore <= 55
  ? 'Complete Real Estate Operations System'
  : qualificationScore >= 60 && systemHealthScore <= 70
  ? 'Real Estate Lead Conversion System'
  : qualificationScore < bGradeMin
  ? 'Educational nurture - no custom proposal yet'
  : 'Lead Follow-Up Foundation';

// Indicative values straight from spec section 2.5 (Paid services behind the lead magnet).
const estimatedValueByOffer = {
  'Complete Real Estate Operations System': '8000-15000+',
  'Real Estate Lead Conversion System': '5000-8000',
  'Lead Follow-Up Foundation': '2500-4000',
  'Educational nurture - no custom proposal yet': ''
};

return [{ json: {
  ...input,
  system_health_score: systemHealthScore,
  qualification_score: qualificationScore,
  lead_grade: grade,
  weakest_categories: weakest,
  recommended_offer: recommendedOffer,
  estimated_value: estimatedValueByOffer[recommendedOffer] || '',
  scoring_version: config.SYSTEM_VERSION || '1.0',
  config_loom_sla_hours: Number(config.LOOM_SLA_HOURS) || 24,
  config_followup_1_days: Number(config.FOLLOWUP_1_DAYS) || 3
}}];

function uuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const searchEmail = $json.work_email;
const searchWebsite = $json.website;
const emailMatchRaw = $('GS - Lookup Existing Lead').first()?.json;
const emailMatch = (emailMatchRaw && emailMatchRaw.lead_id && emailMatchRaw.work_email === searchEmail) ? emailMatchRaw : null;
const domainMatchRaw = $('GS - Lookup Existing Lead by Domain').first()?.json;
const domainMatch = (domainMatchRaw && domainMatchRaw.lead_id && domainMatchRaw.website === searchWebsite) ? domainMatchRaw : null;
const isExisting = !!(emailMatch && emailMatch.lead_id);
const isDomainMatch = !!(domainMatch && domainMatch.lead_id && domainMatch.work_email !== $json.work_email);

const grade = $json.lead_grade;
const nextAction = grade === 'A'
  ? 'Research + personalized Loom + same-day contact'
  : grade === 'B'
  ? 'Scheduled follow-up sequence'
  : 'Light nurture';
const loomSlaHours = Number($json.config_loom_sla_hours) || 24;
const followup1Days = Number($json.config_followup_1_days) || 3;
const nextActionAtUtc = grade === 'A'
  ? new Date(Date.now() + loomSlaHours * 3600 * 1000).toISOString()
  : new Date(Date.now() + followup1Days * 24 * 3600 * 1000).toISOString();

return [{
  json: {
    ...$json,
    lead_id: isExisting ? emailMatch.lead_id : uuid(),
    created_at_utc: isExisting ? emailMatch.created_at_utc : new Date().toISOString(),
    updated_at_utc: new Date().toISOString(),
    last_activity_at_utc: new Date().toISOString(),
    status: isExisting ? (emailMatch.status || 'New submission') : 'New submission',
    next_action: nextAction,
    next_action_at_utc: nextActionAtUtc,
    followup_step: isExisting ? (emailMatch.followup_step || 0) : 0,
    replied: isExisting ? emailMatch.replied : false,
    booking_status: isExisting ? (emailMatch.booking_status || 'Not booked') : 'Not booked',
    deal_status: isExisting ? (emailMatch.deal_status || 'Open') : 'Open',
    consent_status: 'Granted',
    suppressed: false,
    possible_duplicate_account: isDomainMatch,
    related_lead_id: isDomainMatch ? domainMatch.lead_id : '',
    source: $json.utm_source || $json.referrer_url || 'direct',
    campaign: $json.utm_campaign || '',
    lead_sources: Array.isArray($json.lead_sources) ? $json.lead_sources.join(', ') : ($json.lead_sources || ''),
    weakest_categories: JSON.stringify($json.weakest_categories || [])
  }
}];
